import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FaTachometerAlt, FaUserAlt, FaCalendarAlt, FaEdit, FaChalkboardTeacher, FaCommentDots, FaCogs, FaSignOutAlt } from 'react-icons/fa';

const Nav = ({ isSidebarOpen }) => {
  const navigate = useNavigate();

  const handleLogout = () => {
    // Hapus token autentikasi dan role dari localStorage
    localStorage.removeItem('token');
    localStorage.removeItem('role');
    // Redirect ke halaman login
    navigate('/login');
  };

  return (
    <aside className={`w-64 bg-teal-700 text-white flex-shrink-0 transition-all duration-300 ${isSidebarOpen ? 'block' : 'w-[83px]'} p-4`}>
      <nav>
        <ul className="space-y-6">
          <li className="text-xl">
            <a href="/DashboardAdmin" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaTachometerAlt className="w-8 h-8 inline-block mr-3" /> {isSidebarOpen && 'Dashboard'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/Pendaftar" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaUserAlt className="inline-block mr-3" /> {isSidebarOpen && 'Pendaftar'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/Pembayaran" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaCalendarAlt className="inline-block mr-3" /> {isSidebarOpen && 'Pembayaran'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/Jadwal" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaChalkboardTeacher className="inline-block mr-3" /> {isSidebarOpen && 'Jadwal'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/Absen" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaEdit className="inline-block mr-3" /> {isSidebarOpen && 'Presensi'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/ChatAdmin" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaCommentDots className="inline-block mr-3" /> {isSidebarOpen && 'Chat'}
            </a>
          </li>
          <li className="text-xl">
            <a href="/Settings" className="flex items-center px-4 py-3 rounded-lg hover:bg-teal-600 transition duration-200">
              <FaCogs className="inline-block mr-3" /> {isSidebarOpen && 'Settings'}
            </a>
          </li>
          <li className="text-xl">
            <button onClick={handleLogout} className="flex items-center w-full text-left px-4 py-3 rounded-lg hover:bg-red-600 hover:text-white transition duration-200">
              <FaSignOutAlt className="inline-block mr-3" /> {isSidebarOpen && 'Logout'}
            </button>
          </li>
        </ul>
      </nav>
    </aside>
  );
};

export default Nav;
